    $qo=mysqli_query($conn,"SELECT fj.*,COALESCE(GROUP_CONCAT(DISTINCT CONCAT(b.nm_brg,' (',COALESCE(dj.ukuran,'M'),')') ORDER BY b.nm_brg SEPARATOR ', '),'-') AS nm_brg FROM faktur_jual fj LEFT JOIN detal_jual dj ON dj.no_faktur=fj.no_faktur LEFT JOIN barang b ON b.id_brg=dj.id_brg WHERE fj.id_member={$id} GROUP BY fj.id_faktur,fj.no_faktur,fj.id_member,fj.tgl_faktur,fj.total,fj.status,fj.order_status,fj.catatan_admin,fj.tgl_approve,fj.tgl_order ORDER BY fj.tgl_order DESC,fj.id_faktur DESC");
    $qs=mysqli_query($conn,"SELECT COUNT(*) AS jml,COALESCE(SUM(total),0) AS sum FROM faktur_jual WHERE id_member={$id}"); $s=$qs?mysqli_fetch_assoc($qs):[]; $meta=order_status_meta();
?>
<div class="page-head"><div><h1>Detail Pelanggan</h1><p>Informasi pelanggan dan riwayat pesanan.</p></div><a class="btn btn-secondary" href="index.php?menu=member"><i class="bi bi-arrow-left"></i> Kembali</a></div>
<div class="detail-grid"><div class="table-card" style="padding:24px;text-align:center;"><div class="account-photo" style="width:120px;height:120px;border-radius:50%;margin:0 auto 14px;display:grid;place-items:center;overflow:hidden;background:linear-gradient(135deg,#0e2347,#d7b45a);color:#fff;"><?php if($foto):?><img src="../<?php echo e($foto);?>" alt="" style="width:100%;height:100%;object-fit:cover;"><?php else:?><i class="bi bi-person-fill" style="font-size:54px;"></i><?php endif;?></div><h2 style="margin:0 0 4px;"><?php echo e($m['nm_member']);?></h2><div class="kv-list" style="margin-top:18px;text-align:left;"><div class="kv-row"><span>Username</span><b><?php echo e($m['username']);?></b></div><div class="kv-row"><span>Email</span><b><?php echo e($m['email']?:'-');?></b></div><div class="kv-row"><span>No HP</span><b><?php echo e($m['no_hp']?:'-');?></b></div><div class="kv-row"><span>Total Order</span><b><?php echo (int)($s['jml']??0);?></b></div><div class="kv-row"><span>Total Belanja</span><b style="color:var(--accent);"><?php echo rupiah($s['sum']??0);?></b></div></div></div>
<div class="table-card"><div class="table-header"><div><h2>Riwayat Pesanan</h2><p>Status pesanan pelanggan.</p></div></div><div class="table-wrap"><table class="data-table"><thead><tr><th>No Pesanan</th><th>Tanggal</th><th>Produk</th><th>Total</th><th>Status</th><th>Aksi</th></tr></thead><tbody><?php if($qo&&mysqli_num_rows($qo)>0):while($r=mysqli_fetch_assoc($qo)):$os=$r['order_status']==='completed'?'delivered':$r['order_status'];?><tr><td><b><?php echo e($r['no_faktur']);?></b></td><td><?php echo e(date('d M Y',strtotime($r['tgl_order']?:$r['tgl_faktur'])));?></td><td><?php echo e($r['nm_brg']);?></td><td><?php echo rupiah($r['total']);?></td><td><span class="ostat <?php echo e($meta[$os]['class']??'pending');?>"><?php echo e(order_status_label($os));?></span></td><td><a class="btn-edit" href="index.php?menu=orders&status=all&act=detail&no=<?php echo e($r['no_faktur']);?>">Details</a></td></tr><?php endwhile;else:?><tr><td colspan="6" class="empty-state">Belum ada pesanan.</td></tr><?php endif;?></tbody></table></div></div></div>
<?php return; }
